from __future__ import annotations

import base64
import binascii
import hashlib
import hmac
import json
import os
import re
from collections.abc import Callable, Iterable
from dataclasses import dataclass
from typing import Any
from urllib.parse import parse_qsl

from .content import ContentError, ContentStore
from .lifecycle import (
    BLOCKING_STATES,
    MAX_REASON_LENGTH,
    REASON_REQUIRED_STATES,
    STATE_VALUES,
    LifecycleError,
    LifecycleRecord,
    LifecycleStore,
)
from .resources import (
    CATEGORIES,
    DependencyError,
    Resource,
    ResourceStore,
    ResourceValidationError,
)
from .vulnerabilities import (
    SEVERITY_VALUES,
    VulnerabilityError,
    VulnerabilityStore,
    VulnerabilityValidationError,
    build_vulnerability_fields,
)

StartResponse = Callable[[str, list[tuple[str, str]]], Any]

#: Process-local storage; records are not persisted across restarts.
store = ResourceStore()

#: Process-local chunk sessions and finalized content; also never persisted.
content_store = ContentStore()

#: Process-local lifecycle states; cleared on restart like everything else.
lifecycle_store = LifecycleStore()

#: Process-local vulnerability alerts; cleared on restart like the rest.
vulnerability_store = VulnerabilityStore()


def reset_state() -> None:
    """Clear every in-process store (test and tooling helper)."""

    store.reset()
    content_store.reset()
    lifecycle_store.reset()
    vulnerability_store.reset()

#: Listing defaults and bounds.
DEFAULT_LIMIT = 50
MAX_LIMIT = 100
_LIST_PARAMS = frozenset({"category", "name", "digest", "limit", "cursor"})
_CATEGORY_VALUES = frozenset(CATEGORIES)
_DIGEST_PATTERN = re.compile(r"[0-9a-fA-F]{64}")
_POSITIVE_INT_PATTERN = re.compile(r"[1-9][0-9]*")
_NON_NEGATIVE_INT_PATTERN = re.compile(r"0|[1-9][0-9]*")
_OCTET_STREAM_CONTENT_TYPE = "application/octet-stream"
_TOTAL_CHUNKS_HEADER = "HTTP_X_TOTAL_CHUNKS"
_CONTENT_DIGEST_HEADER = "HTTP_X_CONTENT_DIGEST"
_TOTAL_CHUNKS_HEADER_NAME = "X-Total-Chunks"
_CONTENT_DIGEST_HEADER_NAME = "X-Content-Digest"

#: Random per-process key so cursors cannot be forged and never survive a
#: restart; nothing here is persisted to disk.
_cursor_key = os.urandom(32)


class ListQueryError(ValueError):
    """A list request contained invalid query parameters or cursor."""


@dataclass(frozen=True, slots=True)
class ListQuery:
    category: str | None
    name: str | None
    digest: str | None
    limit: int
    offset: int
    paged: bool


def _cursor_signature(
    category: str, name: str, digest: str, limit: int, offset: int
) -> bytes:
    mac = hmac.new(_cursor_key, b"list-cursor-v1", hashlib.sha256)
    for part in (category, name, digest, str(limit)):
        encoded = part.encode("utf-8")
        mac.update(len(encoded).to_bytes(4, "big"))
        mac.update(encoded)
    mac.update(offset.to_bytes(8, "big"))
    return mac.digest()


def _b64encode(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _b64decode(token: str) -> bytes:
    return base64.urlsafe_b64decode(token + "=" * (-len(token) % 4))


def _encode_cursor(
    category: str, name: str, digest: str, limit: int, offset: int
) -> str:
    return _b64encode(str(offset).encode("ascii")) + "." + _b64encode(
        _cursor_signature(category, name, digest, limit, offset)
    )


def _decode_cursor(
    raw: str, category: str, name: str, digest: str, limit: int
) -> int:
    """Return the offset encoded by a cursor.

    Raises :class:`ListQueryError` when the cursor is forged, corrupted or
    was issued for different filter conditions or limit.
    """

    token_b64, dot, sig_b64 = raw.partition(".")
    if not dot or not token_b64 or not sig_b64:
        raise ListQueryError("Cursor is malformed.")
    try:
        token = _b64decode(token_b64)
        sig = _b64decode(sig_b64)
    except (binascii.Error, ValueError):
        raise ListQueryError("Cursor is malformed.") from None

    if not token.isdigit() or token.startswith(b"0") or int(token) <= 0:
        raise ListQueryError("Cursor is malformed.")
    offset = int(token)

    expected = _cursor_signature(category, name, digest, limit, offset)
    if not hmac.compare_digest(sig, expected):
        raise ListQueryError("Cursor is not valid for this request.")
    return offset


def parse_list_query(query_string: str) -> ListQuery:
    """Parse and validate the query string for ``GET /resources``."""

    pairs = parse_qsl(query_string, keep_blank_values=True, strict_parsing=False)
    seen: set[str] = set()
    raw_values: dict[str, str] = {}
    for key, value in pairs:
        if key not in _LIST_PARAMS:
            raise ListQueryError(f"Unknown query parameter: {key!r}.")
        if key in seen:
            raise ListQueryError(f"Query parameter {key!r} must not be repeated.")
        seen.add(key)
        raw_values[key] = value

    category: str | None = None
    if "category" in raw_values:
        value = raw_values["category"]
        if value == "":
            raise ListQueryError("Category must not be empty.")
        if value.lower() not in _CATEGORY_VALUES:
            allowed = ", ".join(CATEGORIES)
            raise ListQueryError(
                f"Category must be one of: {allowed} (case-insensitive)."
            )
        category = value.lower()

    name: str | None = None
    if "name" in raw_values:
        value = raw_values["name"]
        # Exact, case-sensitive comparison; no trimming or folding.
        if value == "":
            raise ListQueryError("Name must not be empty.")
        name = value

    digest: str | None = None
    if "digest" in raw_values:
        value = raw_values["digest"]
        if _DIGEST_PATTERN.fullmatch(value) is None:
            raise ListQueryError(
                "Digest must be a 64-character hexadecimal string."
            )
        digest = value.lower()

    limit = DEFAULT_LIMIT
    if "limit" in raw_values:
        value = raw_values["limit"]
        if _POSITIVE_INT_PATTERN.fullmatch(value) is None:
            raise ListQueryError(
                f"Limit must be a positive integer no greater than {MAX_LIMIT}."
            )
        limit = int(value)
        if limit > MAX_LIMIT:
            raise ListQueryError(
                f"Limit must be a positive integer no greater than {MAX_LIMIT}."
            )

    offset = 0
    if "cursor" in raw_values:
        value = raw_values["cursor"]
        if value == "":
            raise ListQueryError("Cursor is malformed.")
        offset = _decode_cursor(
            value, category or "", name or "", digest or "", limit
        )

    paged = bool(seen)
    return ListQuery(
        category=category,
        name=name,
        digest=digest,
        limit=limit,
        offset=offset,
        paged=paged,
    )


def _handle_resources_get(
    environ: dict[str, Any], start_response: StartResponse
) -> Iterable[bytes]:
    try:
        query = parse_list_query(str(environ.get("QUERY_STRING", "")))
    except ListQueryError as exc:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            str(exc),
        )

    if not query.paged:
        # No filtering or pagination parameters: preserve the original shape.
        return _json_response(
            start_response,
            "200 OK",
            {"resources": [r.to_dict() for r in store.list_all()]},
            trailing_newline=True,
        )

    matched = store.query(
        category=query.category, name=query.name, digest=query.digest
    )
    page = matched[query.offset : query.offset + query.limit]
    next_offset = query.offset + len(page)
    next_cursor: str | None = None
    if next_offset < len(matched):
        next_cursor = _encode_cursor(
            query.category or "",
            query.name or "",
            query.digest or "",
            query.limit,
            next_offset,
        )

    return _json_response(
        start_response,
        "200 OK",
        {"resources": [r.to_dict() for r in page], "next_cursor": next_cursor},
        trailing_newline=True,
    )


def _json_response(
    start_response: StartResponse,
    status: str,
    payload: dict[str, object],
    *,
    extra_headers: list[tuple[str, str]] | None = None,
    trailing_newline: bool = False,
) -> Iterable[bytes]:
    body = json.dumps(
        payload,
        ensure_ascii=False,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    if trailing_newline:
        body += b"\n"
    headers = [
        ("Content-Type", "application/json; charset=utf-8"),
        ("Content-Length", str(len(body))),
    ]
    if extra_headers:
        headers.extend(extra_headers)
    start_response(status, headers)
    return [body]


def _error(
    start_response: StartResponse,
    status: str,
    code: str,
    message: str,
    *,
    allowed: str | None = None,
    trailing_newline: bool = True,
) -> Iterable[bytes]:
    headers = []
    if allowed is not None:
        headers.append(("Allow", allowed))
    return _json_response(
        start_response,
        status,
        {"error": code, "message": message},
        extra_headers=headers,
        trailing_newline=trailing_newline,
    )


def _resource_response(
    start_response: StartResponse, status: str, resource: Resource
) -> Iterable[bytes]:
    return _json_response(
        start_response,
        status,
        resource.to_dict(),
        trailing_newline=True,
    )


def _read_body(environ: dict[str, Any]) -> bytes:
    try:
        length = int(environ.get("CONTENT_LENGTH") or 0)
    except (TypeError, ValueError):
        length = 0
    if length <= 0:
        return b""
    return environ["wsgi.input"].read(length)


def _handle_resources_post(
    environ: dict[str, Any], start_response: StartResponse
) -> Iterable[bytes]:
    raw = _read_body(environ)
    if not raw:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body is empty.",
        )
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be valid UTF-8 JSON.",
        )

    try:
        created, existing = store.add(payload)
    except ResourceValidationError as exc:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            exc.message,
        )

    if existing is not None:
        # Never overwrite or merge with the original record.
        return _error(
            start_response,
            "409 Conflict",
            "duplicate_resource",
            "A resource with the same category, name and digest already exists.",
        )

    assert created is not None
    return _resource_response(start_response, "201 Created", created)


def _handle_resource_item(
    method: str, raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    if method != "GET":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    if not raw_id:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Resource id must not be empty.",
        )
    if "/" in raw_id or "\\" in raw_id:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Resource id must not contain path separators.",
        )

    resource = store.get(raw_id)
    if resource is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    return _resource_response(start_response, "200 OK", resource)


def _validate_path_id(raw_id: str) -> str | None:
    """Return a stable error message for an invalid path id, else ``None``."""

    if not raw_id:
        return "Resource id must not be empty."
    if "/" in raw_id or "\\" in raw_id:
        return "Resource id must not contain path separators."
    return None


def _query_parameter_error(environ: dict[str, Any]) -> str | None:
    """Reject any query parameter on endpoints that declare none."""

    query_string = str(environ.get("QUERY_STRING", ""))
    if parse_qsl(query_string, keep_blank_values=True):
        return "This endpoint does not accept query parameters."
    return None


def _handle_dependencies_post(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )

    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    raw = _read_body(environ)
    if not raw:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body is empty.",
        )
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be valid UTF-8 JSON.",
        )

    if not isinstance(payload, dict):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be a JSON object.",
        )
    unknown_fields = set(payload) - {"dependency_id"}
    if unknown_fields:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            f"Unknown field: {sorted(unknown_fields)[0]!r}.",
        )
    if "dependency_id" not in payload:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Missing required field: 'dependency_id'.",
        )
    dependency_id = payload["dependency_id"]
    if not isinstance(dependency_id, str) or not dependency_id:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Field 'dependency_id' must be a non-empty string.",
        )
    if "/" in dependency_id or "\\" in dependency_id:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Field 'dependency_id' must not contain path separators.",
        )

    # Both endpoints must already be registered; never auto-create.
    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )
    if store.get(dependency_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with dependency_id.",
        )

    try:
        store.add_dependency(raw_id, dependency_id)
    except DependencyError as exc:
        return _error(
            start_response,
            "409 Conflict",
            exc.code,
            exc.message,
        )

    return _json_response(
        start_response,
        "201 Created",
        {"resource_id": raw_id, "dependency_id": dependency_id},
        trailing_newline=True,
    )


def _handle_dependencies_get(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )
    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )
    return _json_response(
        start_response,
        "200 OK",
        {"dependencies": store.list_dependencies(raw_id)},
        trailing_newline=True,
    )


def _handle_dependencies(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method == "POST":
        return _handle_dependencies_post(environ, raw_id, start_response)
    if method == "GET":
        return _handle_dependencies_get(environ, raw_id, start_response)
    return _error(
        start_response,
        "405 Method Not Allowed",
        "method_not_allowed",
        f"Method {method} is not allowed for this path.",
        allowed="GET, POST",
    )


def _handle_impact(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "GET":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )
    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )
    return _json_response(
        start_response,
        "200 OK",
        {"resources": store.list_impact(raw_id)},
        trailing_newline=True,
    )


def _read_declared_body(environ: dict[str, Any]) -> tuple[bytes | None, str | None]:
    """Read exactly the declared request body for content verification.

    Returns ``(body, None)`` on success or ``(None, message)`` when the
    ``Content-Length`` header is missing or malformed, the stream cannot be
    read, or fewer bytes than declared are available. An explicitly declared
    length of zero is a valid empty body, not a missing one.
    """

    raw_length = environ.get("CONTENT_LENGTH")
    if not isinstance(raw_length, str):
        return None, "Content-Length header is required."
    if _NON_NEGATIVE_INT_PATTERN.fullmatch(raw_length) is None:
        return None, "Content-Length header must be a non-negative integer."
    length = int(raw_length)

    try:
        body = environ["wsgi.input"].read(length)
    except Exception:
        return None, "Request body could not be read."
    if not isinstance(body, (bytes, bytearray)) or len(body) != length:
        return None, "Request body is incomplete."
    return bytes(body), None


def _handle_verify(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "POST":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="POST",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    content_type = str(environ.get("CONTENT_TYPE", ""))
    if content_type.lower() != _OCTET_STREAM_CONTENT_TYPE:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Content-Type must be application/octet-stream.",
        )

    body, body_error = _read_declared_body(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )
    assert body is not None

    resource = store.get(raw_id)
    if resource is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    digest = hashlib.sha256(body).hexdigest()
    return _json_response(
        start_response,
        "200 OK",
        {"id": resource.id, "digest": digest, "valid": digest == resource.digest},
        trailing_newline=True,
    )


def _chunk_status_response(
    start_response: StartResponse,
    status: str,
    resource_id: str,
    index: int,
    total: int,
    digest: str,
    received: int,
) -> Iterable[bytes]:
    return _json_response(
        start_response,
        status,
        {
            "id": resource_id,
            "index": index,
            "total_chunks": total,
            "received_chunks": received,
            "digest": digest,
        },
        trailing_newline=True,
    )


def _handle_chunk(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    raw_index: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "POST":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="POST",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    # The chunk index is part of the path and must be a non-negative decimal
    # integer; anything else (including separators) is a bad request.
    if _NON_NEGATIVE_INT_PATTERN.fullmatch(raw_index) is None:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Chunk index must be a non-negative decimal integer.",
        )
    index = int(raw_index)

    content_type = str(environ.get("CONTENT_TYPE", ""))
    if content_type.lower() != _OCTET_STREAM_CONTENT_TYPE:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Content-Type must be application/octet-stream.",
        )

    raw_total = environ.get(_TOTAL_CHUNKS_HEADER)
    if not isinstance(raw_total, str) or not raw_total:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            f"{_TOTAL_CHUNKS_HEADER_NAME} header is required.",
        )
    if _POSITIVE_INT_PATTERN.fullmatch(raw_total) is None:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            f"{_TOTAL_CHUNKS_HEADER_NAME} header must be a positive integer.",
        )
    total = int(raw_total)
    if index >= total:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Chunk index must be smaller than the total chunk count.",
        )

    raw_digest = environ.get(_CONTENT_DIGEST_HEADER)
    if not isinstance(raw_digest, str) or _DIGEST_PATTERN.fullmatch(
        raw_digest
    ) is None:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            f"{_CONTENT_DIGEST_HEADER_NAME} header must be a 64-character "
            "hexadecimal digest.",
        )
    digest = raw_digest.lower()

    body, body_error = _read_declared_body(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )
    assert body is not None

    resource = store.get(raw_id)
    if resource is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    if content_store.is_complete(raw_id):
        return _error(
            start_response,
            "409 Conflict",
            "content_already_complete",
            "Content for this resource is already complete.",
        )

    try:
        created, received = content_store.add_chunk(
            raw_id, total, digest, resource.digest, index, body
        )
    except ContentError as exc:
        return _error(
            start_response, "409 Conflict", exc.code, exc.message
        )

    return _chunk_status_response(
        start_response,
        "201 Created" if created else "200 OK",
        raw_id,
        index,
        total,
        digest,
        received,
    )


def _handle_chunks_status(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "GET":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    # Read-only: no session is created when upload has not started.
    status = content_store.session_status(raw_id)
    if status is None:
        return _error(
            start_response,
            "409 Conflict",
            "chunks_not_started",
            "No chunk upload has been started for this resource.",
        )

    return _json_response(
        start_response,
        "200 OK",
        {
            "id": raw_id,
            "digest": status.digest,
            "total_chunks": status.total,
            "received_chunks": status.received_chunks,
            "missing_chunks": list(status.missing_chunks),
            "complete": status.complete,
            "size": status.size,
        },
        trailing_newline=True,
    )


def _handle_assemble(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "POST":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="POST",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    try:
        digest, size = content_store.assemble(raw_id)
    except ContentError as exc:
        return _error(
            start_response, "409 Conflict", exc.code, exc.message
        )

    return _json_response(
        start_response,
        "201 Created",
        {"id": raw_id, "digest": digest, "size": size},
        trailing_newline=True,
    )


def _handle_content(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "GET":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    try:
        body = content_store.get_content(raw_id)
    except ContentError as exc:
        return _error(
            start_response, "409 Conflict", exc.code, exc.message
        )

    # The finalized artifact is returned as raw bytes only: no JSON wrapper
    # and no trailing newline.
    start_response(
        "200 OK",
        [
            ("Content-Type", "application/octet-stream"),
            ("Content-Length", str(len(body))),
        ],
    )
    return [body]


def _lifecycle_response(
    start_response: StartResponse,
    status: str,
    resource_id: str,
    record: LifecycleRecord,
) -> Iterable[bytes]:
    return _json_response(
        start_response,
        status,
        {"id": resource_id, "state": record.state, "reason": record.reason},
        trailing_newline=True,
    )


def _handle_lifecycle_get(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )
    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )
    return _lifecycle_response(
        start_response, "200 OK", raw_id, lifecycle_store.get(raw_id)
    )


def _handle_lifecycle_post(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    raw = _read_body(environ)
    if not raw:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body is empty.",
        )
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be valid UTF-8 JSON.",
        )

    if not isinstance(payload, dict):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be a JSON object.",
        )
    unknown_fields = set(payload) - {"state", "reason"}
    if unknown_fields:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            f"Unknown field: {sorted(unknown_fields)[0]!r}.",
        )
    if "state" not in payload:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Missing required field: 'state'.",
        )
    target = payload["state"]
    if not isinstance(target, str) or target not in STATE_VALUES:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Field 'state' must be one of: staged, released, withdrawn, "
            "quarantined (case-sensitive).",
        )

    reason: str | None = None
    if "reason" in payload:
        value = payload["reason"]
        if not isinstance(value, str):
            return _error(
                start_response,
                "400 Bad Request",
                "invalid_request",
                "Field 'reason' must be a string.",
            )
        if value == "":
            return _error(
                start_response,
                "400 Bad Request",
                "invalid_request",
                "Field 'reason' must not be empty.",
            )
        if len(value) > MAX_REASON_LENGTH:
            return _error(
                start_response,
                "400 Bad Request",
                "invalid_request",
                f"Field 'reason' must not exceed {MAX_REASON_LENGTH} "
                "Unicode code points.",
            )
        reason = value
    if target in REASON_REQUIRED_STATES and reason is None:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            f"Field 'reason' is required when the target state is "
            f"{target!r}.",
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    current = lifecycle_store.get(raw_id)
    if (current.state, target) == ("staged", "released"):
        # Promotion requires assembled content and healthy dependencies.
        if not content_store.is_complete(raw_id):
            return _error(
                start_response,
                "409 Conflict",
                "content_not_complete",
                "Content for this resource is not complete.",
            )
        for dependency_id in store.list_dependencies(raw_id):
            if lifecycle_store.get(dependency_id).state in BLOCKING_STATES:
                return _error(
                    start_response,
                    "409 Conflict",
                    "dependency_blocked",
                    "A dependency of this resource is withdrawn or "
                    "quarantined.",
                )

    try:
        record = lifecycle_store.apply(current, target, reason)
    except LifecycleError as exc:
        return _error(
            start_response, "409 Conflict", exc.code, exc.message
        )

    # ``apply`` returns the very same record for an idempotent repeat; only a
    # real transition is stored, so a repeat never adds a record.
    if record is not current:
        lifecycle_store.set(raw_id, record)
    return _lifecycle_response(start_response, "200 OK", raw_id, record)


def _handle_lifecycle(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method == "GET":
        return _handle_lifecycle_get(environ, raw_id, start_response)
    if method == "POST":
        return _handle_lifecycle_post(environ, raw_id, start_response)
    return _error(
        start_response,
        "405 Method Not Allowed",
        "method_not_allowed",
        f"Method {method} is not allowed for this path.",
        allowed="GET, POST",
    )


def _handle_vulnerabilities_post(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    raw = _read_body(environ)
    if not raw:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body is empty.",
        )
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be valid UTF-8 JSON.",
        )

    try:
        # Validate the whole body before touching any store, so a bad request
        # can never leave a partial record and always answers 400 (even for a
        # resource that does not exist).
        build_vulnerability_fields(payload)
    except VulnerabilityValidationError as exc:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            exc.message,
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    try:
        record = vulnerability_store.add(raw_id, payload)
    except VulnerabilityError as exc:
        return _error(
            start_response, "409 Conflict", exc.code, exc.message
        )

    return _json_response(
        start_response,
        "201 Created",
        record.to_dict(),
        trailing_newline=True,
    )


def _handle_vulnerabilities_get(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )

    # Only the optional ``severity`` parameter is accepted; unknown or
    # repeated parameters, including a repeated ``severity``, are rejected.
    pairs = parse_qsl(
        str(environ.get("QUERY_STRING", "")),
        keep_blank_values=True,
        strict_parsing=False,
    )
    severity: str | None = None
    for key, value in pairs:
        if key != "severity":
            return _error(
                start_response,
                "400 Bad Request",
                "invalid_request",
                f"Unknown query parameter: {key!r}.",
            )
        if severity is not None:
            return _error(
                start_response,
                "400 Bad Request",
                "invalid_request",
                "Query parameter 'severity' must not be repeated.",
            )
        if value == "" or value.lower() not in SEVERITY_VALUES:
            return _error(
                start_response,
                "400 Bad Request",
                "invalid_request",
                "Severity must be one of: critical, high, medium, low "
                "(case-insensitive).",
            )
        severity = value.lower()

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    records = vulnerability_store.list_for(raw_id, severity)
    return _json_response(
        start_response,
        "200 OK",
        {"vulnerabilities": [record.to_dict() for record in records]},
        trailing_newline=True,
    )


def _handle_vulnerabilities(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method == "POST":
        return _handle_vulnerabilities_post(environ, raw_id, start_response)
    if method == "GET":
        return _handle_vulnerabilities_get(environ, raw_id, start_response)
    return _error(
        start_response,
        "405 Method Not Allowed",
        "method_not_allowed",
        f"Method {method} is not allowed for this path.",
        allowed="GET, POST",
    )


def application(
    environ: dict[str, Any], start_response: StartResponse
) -> Iterable[bytes]:
    try:
        method = str(environ.get("REQUEST_METHOD", "GET")).upper()
        path = str(environ.get("PATH_INFO", "/"))

        if method == "GET" and path == "/health":
            # Kept byte-for-byte compatible with the documented baseline.
            return _json_response(start_response, "200 OK", {"status": "ok"})

        if path == "/resources":
            if method == "GET":
                return _handle_resources_get(environ, start_response)
            if method == "POST":
                return _handle_resources_post(environ, start_response)
            return _error(
                start_response,
                "405 Method Not Allowed",
                "method_not_allowed",
                f"Method {method} is not allowed for this path.",
                allowed="GET, POST",
            )

        if path.startswith("/resources/"):
            suffix = path[len("/resources/"):]
            head, separator, tail = suffix.partition("/")
            if separator and tail == "dependencies":
                return _handle_dependencies(
                    method, environ, head, start_response
                )
            if separator and tail == "impact":
                return _handle_impact(
                    method, environ, head, start_response
                )
            if separator and tail == "verify":
                return _handle_verify(
                    method, environ, head, start_response
                )
            if separator and tail == "assemble":
                return _handle_assemble(
                    method, environ, head, start_response
                )
            if separator and tail == "content":
                return _handle_content(
                    method, environ, head, start_response
                )
            if separator and tail == "lifecycle":
                return _handle_lifecycle(
                    method, environ, head, start_response
                )
            if separator and tail == "vulnerabilities":
                return _handle_vulnerabilities(
                    method, environ, head, start_response
                )
            if separator and tail == "chunks/status":
                return _handle_chunks_status(
                    method, environ, head, start_response
                )
            if separator and tail.startswith("chunks/"):
                return _handle_chunk(
                    method, environ, head, tail[len("chunks/"):],
                    start_response,
                )
            if separator and tail == "chunks":
                # The collection itself cannot be addressed: a chunk index is
                # required, so POST is a bad request and other methods 405.
                return _handle_chunk(
                    method, environ, head, "", start_response
                )
            if separator and suffix.endswith("/verify"):
                # The id segment itself contained a path separator; let the
                # verify handler reject it without reading business data.
                return _handle_verify(
                    method, environ, suffix[: -len("/verify")], start_response
                )
            if separator and suffix.endswith("/chunks/status"):
                # Fallback for a separator inside the id segment so the
                # status handler rejects it without creating any state.
                return _handle_chunks_status(
                    method,
                    environ,
                    suffix[: -len("/chunks/status")],
                    start_response,
                )
            if separator and "/chunks/" in suffix:
                # Same fallback for chunk paths with a separator in the id.
                malformed_id, _, raw_index = suffix.rpartition("/chunks/")
                return _handle_chunk(
                    method, environ, malformed_id, raw_index, start_response
                )
            if separator and suffix.endswith("/assemble"):
                return _handle_assemble(
                    method, environ, suffix[: -len("/assemble")], start_response
                )
            if separator and suffix.endswith("/content"):
                return _handle_content(
                    method, environ, suffix[: -len("/content")], start_response
                )
            if separator and suffix.endswith("/lifecycle"):
                return _handle_lifecycle(
                    method,
                    environ,
                    suffix[: -len("/lifecycle")],
                    start_response,
                )
            if separator and suffix.endswith("/vulnerabilities"):
                # Fallback for a separator inside the id segment so the
                # handler rejects it without recording any alert.
                return _handle_vulnerabilities(
                    method,
                    environ,
                    suffix[: -len("/vulnerabilities")],
                    start_response,
                )
            # Any other suffix keeps the baseline item semantics (embedded
            # separators are rejected by the item handler).
            return _handle_resource_item(
                method, suffix, start_response
            )

        # Unknown paths and undeclared methods on /health stay as before.
        return _json_response(
            start_response,
            "404 Not Found",
            {"error": "not_found", "message": "The requested resource does not exist."},
        )
    except Exception:  # pragma: no cover - defensive boundary
        # Clients must only ever see agreed statuses, never a stack trace.
        return _error(
            start_response,
            "500 Internal Server Error",
            "internal_error",
            "An unexpected error occurred.",
        )

"""In-process resource registry and registration validation."""

from __future__ import annotations

import re
import uuid
from dataclasses import dataclass

#: The four resource categories exposed by the service.
CATEGORIES: tuple[str, ...] = ("code", "model", "dataset", "artifact")
_CATEGORY_VALUES = frozenset(CATEGORIES)

_DIGEST_PATTERN = re.compile(r"[0-9a-fA-F]{64}")
_ALLOWED_FIELDS = frozenset({"name", "category", "digest", "source"})
_REQUIRED_FIELDS = ("name", "category", "digest")


class ResourceValidationError(ValueError):
    """A registration payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


class DependencyError(ValueError):
    """A dependency relation could not be established.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class Resource:
    """A single registered resource record."""

    id: str
    name: str
    category: str
    digest: str
    source: str | None

    def to_dict(self) -> dict[str, object]:
        return {
            "id": self.id,
            "name": self.name,
            "category": self.category,
            "digest": self.digest,
            "source": self.source,
        }


def _require_non_empty_string(value: object, label: str) -> str:
    if not isinstance(value, str):
        raise ResourceValidationError(f"{label} must be a string.")
    if not value.strip():
        raise ResourceValidationError(f"{label} must not be empty.")
    return value


def build_resource_fields(
    payload: object,
) -> tuple[str, str, str, str | None]:
    """Validate a decoded JSON payload and return normalized field values."""

    if not isinstance(payload, dict):
        raise ResourceValidationError("Request body must be a JSON object.")

    unknown_fields = set(payload) - _ALLOWED_FIELDS
    if unknown_fields:
        raise ResourceValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    for field in _REQUIRED_FIELDS:
        if field not in payload:
            raise ResourceValidationError(
                f"Missing required field: {field!r}."
            )

    name = _require_non_empty_string(payload["name"], "Name")

    category_raw = payload["category"]
    if not isinstance(category_raw, str):
        raise ResourceValidationError("Category must be a string.")
    category = category_raw.lower()
    if category not in _CATEGORY_VALUES:
        allowed = ", ".join(CATEGORIES)
        raise ResourceValidationError(
            f"Category must be one of: {allowed} (case-insensitive)."
        )

    digest_raw = payload["digest"]
    if not isinstance(digest_raw, str) or _DIGEST_PATTERN.fullmatch(
        digest_raw
    ) is None:
        raise ResourceValidationError(
            "Digest must be a 64-character hexadecimal string."
        )
    # Hexadecimal digests are case-insensitive; store them canonically.
    digest = digest_raw.lower()

    source: str | None = None
    if "source" in payload:
        source = _require_non_empty_string(payload["source"], "Source")

    return name, category, digest, source


class ResourceStore:
    """Process-local, insertion-ordered resource storage."""

    def __init__(self) -> None:
        self._resources: list[Resource] = []
        self._by_id: dict[str, Resource] = {}
        self._key_to_id: dict[tuple[str, str, str], str] = {}
        # resource id -> ids it directly depends on, and the reverse view.
        self._dependencies: dict[str, set[str]] = {}
        self._dependents: dict[str, set[str]] = {}

    def reset(self) -> None:
        self._resources.clear()
        self._resources = []
        self._by_id = {}
        self._key_to_id = {}
        self._dependencies = {}
        self._dependents = {}

    def list_all(self) -> list[Resource]:
        return list(self._resources)

    def query(
        self,
        *,
        category: str | None = None,
        name: str | None = None,
        digest: str | None = None,
    ) -> list[Resource]:
        """Return matching resources in creation order.

        ``category`` is compared case-insensitively, ``name`` is an exact
        string match and ``digest`` is compared against the stored lowercase
        form. Multiple conditions are AND-ed together.
        """

        if category is None and name is None and digest is None:
            return list(self._resources)

        matches: list[Resource] = []
        for resource in self._resources:
            if category is not None and resource.category != category.lower():
                continue
            if name is not None and resource.name != name:
                continue
            if digest is not None and resource.digest != digest:
                continue
            matches.append(resource)
        return matches

    def get(self, resource_id: str) -> Resource | None:
        return self._by_id.get(resource_id)

    def add(
        self, payload: object
    ) -> tuple[Resource | None, Resource | None]:
        """Validate and store a resource.

        Returns ``(created, None)`` on success or ``(None, existing)`` when
        the same category, name and digest are already registered.
        """

        name, category, digest, source = build_resource_fields(payload)
        key = (category, name, digest)
        existing_id = self._key_to_id.get(key)
        if existing_id is not None:
            return None, self._by_id[existing_id]

        resource = Resource(
            id=uuid.uuid4().hex,
            name=name,
            category=category,
            digest=digest,
            source=source,
        )
        self._resources.append(resource)
        self._by_id[resource.id] = resource
        self._key_to_id[key] = resource.id
        self._dependencies[resource.id] = set()
        self._dependents[resource.id] = set()
        return resource, None

    # --- Dependencies ------------------------------------------------------

    def _reachable(self, start: str, graph: dict[str, set[str]]) -> set[str]:
        """Transitive closure of ``start`` through ``graph`` (start excluded)."""

        seen: set[str] = set()
        stack = list(graph.get(start, ()))
        while stack:
            node = stack.pop()
            if node in seen:
                continue
            seen.add(node)
            stack.extend(graph.get(node, ()))
        return seen

    def _registration_order(self, ids: set[str]) -> list[str]:
        return [r.id for r in self._resources if r.id in ids]

    def add_dependency(self, resource_id: str, dependency_id: str) -> None:
        """Record that ``resource_id`` depends on ``dependency_id``.

        Both resources must already be registered. Raises
        :class:`DependencyError` with code ``duplicate_dependency`` when the
        same-direction relation already exists, or ``dependency_cycle`` for a
        self loop or a relation that would introduce a cycle; in either case
        the graph is left unchanged.
        """

        if resource_id == dependency_id:
            raise DependencyError(
                "dependency_cycle", "A resource must not depend on itself."
            )

        existing = self._dependencies.get(resource_id, ())
        if dependency_id in existing:
            raise DependencyError(
                "duplicate_dependency",
                "This dependency relation already exists.",
            )

        # Adding resource_id -> dependency_id creates a cycle whenever
        # dependency_id can already reach resource_id.
        if resource_id in self._reachable(dependency_id, self._dependencies):
            raise DependencyError(
                "dependency_cycle",
                "This dependency would introduce a cycle.",
            )

        self._dependencies[resource_id].add(dependency_id)
        self._dependents[dependency_id].add(resource_id)

    def list_dependencies(self, resource_id: str) -> list[str]:
        """Return every reachable dependency id in registration order."""

        return self._registration_order(
            self._reachable(resource_id, self._dependencies)
        )

    def list_impact(self, resource_id: str) -> list[str]:
        """Return ids that directly or transitively depend on ``resource_id``.

        The start resource itself is excluded; results are in registration
        order.
        """

        return self._registration_order(
            self._reachable(resource_id, self._dependents)
        )

"""In-process security vulnerability registration for registered resources.

A vulnerability record pairs an advisory identifier with the affected
component, a severity level, a summary and an optional fixed version.
Records are kept per resource in submission order and are never persisted:
stopping or restarting the service clears every alert, and no files are
written. Batching, updates, deletion and concurrency are intentionally out
of scope.
"""

from __future__ import annotations

import uuid
from dataclasses import dataclass

#: The four allowed severity levels; input is case-insensitive but the level
#: is always stored and rendered in lowercase.
SEVERITIES: tuple[str, ...] = ("critical", "high", "medium", "low")
SEVERITY_VALUES = frozenset(SEVERITIES)

#: Length caps, counted in Unicode code points.
MAX_ADVISORY_LENGTH = 256
MAX_COMPONENT_LENGTH = 256
MAX_SUMMARY_LENGTH = 2048
MAX_FIXED_VERSION_LENGTH = 256

#: Fields accepted by the registration request; anything else is rejected.
_ALLOWED_FIELDS = frozenset(
    {"advisory", "component", "severity", "summary", "fixed_version"}
)
_REQUIRED_FIELDS = ("advisory", "component", "severity", "summary")


class VulnerabilityValidationError(ValueError):
    """A registration payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


class VulnerabilityError(ValueError):
    """A vulnerability operation could not proceed.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class Vulnerability:
    """A single vulnerability alert recorded against a resource."""

    id: str
    advisory: str
    component: str
    severity: str
    summary: str
    fixed_version: str | None

    def to_dict(self) -> dict[str, object]:
        return {
            "id": self.id,
            "advisory": self.advisory,
            "component": self.component,
            "severity": self.severity,
            "summary": self.summary,
            "fixed_version": self.fixed_version,
        }


def _required_string(value: object, field: str, limit: int) -> str:
    """Validate a required non-empty string bounded by ``limit`` code points."""

    label = field.capitalize()
    if not isinstance(value, str):
        raise VulnerabilityValidationError(f"Field {field!r} must be a string.")
    if not value:
        raise VulnerabilityValidationError(
            f"Field {field!r} must not be empty."
        )
    if len(value) > limit:
        raise VulnerabilityValidationError(
            f"{label} must not exceed {limit} Unicode code points."
        )
    return value


def build_vulnerability_fields(
    payload: object,
) -> tuple[str, str, str, str, str | None]:
    """Validate a decoded JSON payload and return normalized field values.

    Returns ``(advisory, component, severity, summary, fixed_version)``.
    Severity is matched case-insensitively and normalized to lowercase.
    ``fixed_version`` is ``None`` when omitted.
    """

    if not isinstance(payload, dict):
        raise VulnerabilityValidationError(
            "Request body must be a JSON object."
        )

    unknown_fields = set(payload) - _ALLOWED_FIELDS
    if unknown_fields:
        raise VulnerabilityValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    for field in _REQUIRED_FIELDS:
        if field not in payload:
            raise VulnerabilityValidationError(
                f"Missing required field: {field!r}."
            )

    advisory = _required_string(
        payload["advisory"], "advisory", MAX_ADVISORY_LENGTH
    )
    component = _required_string(
        payload["component"], "component", MAX_COMPONENT_LENGTH
    )

    severity_raw = payload["severity"]
    if not isinstance(severity_raw, str) or not severity_raw:
        raise VulnerabilityValidationError(
            "Field 'severity' must be one of: critical, high, medium, low "
            "(case-insensitive)."
        )
    severity = severity_raw.lower()
    if severity not in SEVERITY_VALUES:
        raise VulnerabilityValidationError(
            "Field 'severity' must be one of: critical, high, medium, low "
            "(case-insensitive)."
        )

    summary = _required_string(
        payload["summary"], "summary", MAX_SUMMARY_LENGTH
    )

    fixed_version: str | None = None
    if "fixed_version" in payload:
        value = payload["fixed_version"]
        if not isinstance(value, str):
            raise VulnerabilityValidationError(
                "Field 'fixed_version' must be a string."
            )
        if not value:
            raise VulnerabilityValidationError(
                "Field 'fixed_version' must not be empty."
            )
        if len(value) > MAX_FIXED_VERSION_LENGTH:
            raise VulnerabilityValidationError(
                f"Fixed version must not exceed {MAX_FIXED_VERSION_LENGTH} "
                "Unicode code points."
            )
        fixed_version = value

    return advisory, component, severity, summary, fixed_version


class VulnerabilityStore:
    """Process-local, submission-ordered vulnerability storage per resource."""

    def __init__(self) -> None:
        # resource id -> alerts in submission order.
        self._records: dict[str, list[Vulnerability]] = {}
        # resource id -> (advisory, component) duplicates already seen.
        self._keys: dict[str, set[tuple[str, str]]] = {}

    def reset(self) -> None:
        self._records = {}
        self._keys = {}

    def add(self, resource_id: str, payload: object) -> Vulnerability:
        """Validate and append a vulnerability alert for ``resource_id``.

        Raises :class:`VulnerabilityValidationError` for an invalid payload
        or :class:`VulnerabilityError` with code ``duplicate_vulnerability``
        when the same advisory identifier and component pair is already
        recorded for the resource; the original alert is left untouched.
        """

        advisory, component, severity, summary, fixed_version = (
            build_vulnerability_fields(payload)
        )
        key = (advisory, component)
        resource_keys = self._keys.setdefault(resource_id, set())
        if key in resource_keys:
            raise VulnerabilityError(
                "duplicate_vulnerability",
                "An alert with the same advisory and component already "
                "exists for this resource.",
            )

        record = Vulnerability(
            id=uuid.uuid4().hex,
            advisory=advisory,
            component=component,
            severity=severity,
            summary=summary,
            fixed_version=fixed_version,
        )
        self._records.setdefault(resource_id, []).append(record)
        resource_keys.add(key)
        return record

    def list_for(
        self, resource_id: str, severity: str | None = None
    ) -> list[Vulnerability]:
        """Return a resource's alerts in submission order.

        With ``severity`` set (already normalized to lowercase), only alerts
        at that level are returned; the relative submission order is kept.
        """

        records = self._records.get(resource_id, ())
        if severity is None:
            return list(records)
        return [record for record in records if record.severity == severity]

"""In-process lifecycle states for registered resources.

Every resource starts in ``staged`` and can be promoted to ``released``
once its content is assembled and its dependencies are healthy, or be
withdrawn or quarantined with a recorded reason. Only the current state
and reason are kept, in the current process memory only: nothing is
persisted and a restart resets every resource to ``staged``.
"""

from __future__ import annotations

from dataclasses import dataclass

#: The fixed set of lifecycle states; names are case-sensitive.
STATES: tuple[str, ...] = ("staged", "released", "withdrawn", "quarantined")
STATE_VALUES = frozenset(STATES)

#: Target states that always require a non-empty reason.
REASON_REQUIRED_STATES = frozenset({"withdrawn", "quarantined"})

#: Maximum reason length, counted in Unicode code points.
MAX_REASON_LENGTH = 1024

#: Permitted state transitions. ``("staged", "released")`` is additionally
#: gated on assembled content and healthy dependencies by the caller.
_ALLOWED_TRANSITIONS = frozenset(
    {
        ("staged", "released"),
        ("staged", "quarantined"),
        ("released", "withdrawn"),
        ("released", "quarantined"),
        ("withdrawn", "staged"),
        ("quarantined", "staged"),
    }
)

#: States that block a dependent resource from being released.
BLOCKING_STATES = frozenset({"withdrawn", "quarantined"})


class LifecycleError(ValueError):
    """A lifecycle transition could not be applied.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class LifecycleRecord:
    """The current lifecycle state of one resource."""

    state: str
    reason: str | None


class LifecycleStore:
    """Process-local current lifecycle state per resource id."""

    def __init__(self) -> None:
        self._records: dict[str, LifecycleRecord] = {}

    def reset(self) -> None:
        self._records = {}

    def get(self, resource_id: str) -> LifecycleRecord:
        """Return the current record; resources default to ``staged``."""

        return self._records.get(
            resource_id, LifecycleRecord(state="staged", reason=None)
        )

    def set(self, resource_id: str, record: LifecycleRecord) -> None:
        self._records[resource_id] = record

    def apply(
        self, current: LifecycleRecord, target: str, reason: str | None
    ) -> LifecycleRecord:
        """Compute the record for a requested transition.

        Resubmitting the current state with the current reason is an
        idempotent no-op and returns the record unchanged. Any other
        same-state request (a reason change) and any transition outside
        the permitted set raises :class:`LifecycleError` with code
        ``invalid_state_transition``; the caller leaves state untouched.
        """

        if target == current.state:
            if reason == current.reason:
                return current
            raise LifecycleError(
                "invalid_state_transition",
                "The recorded reason must not be changed.",
            )
        if (current.state, target) not in _ALLOWED_TRANSITIONS:
            raise LifecycleError(
                "invalid_state_transition",
                f"Transition from {current.state!r} to {target!r} is not "
                "allowed.",
            )
        return LifecycleRecord(state=target, reason=reason)

